<script setup lang="ts">import{onMounted,ref}from'vue';import{ElMessage}from'element-plus';import{useRoute}from'vue-router';import{request}from'../../api/client';const route=useRoute(),detail=ref<any>(null),episodes=ref<any[]>([]);async function load(){try{detail.value=(await request('/api/v1/dramas/'+route.params.id)).drama}catch{detail.value={id:Number(route.params.id),title:'The Contract Wife',description:'A contract marriage turns into a battle of secrets, loyalty and love.',country:'US',language:'en',is_paid:true,price_cents:499}}try{episodes.value=(await request('/api/v1/dramas/'+route.params.id+'/episodes?user_id=1')).items||[]}catch{episodes.value=[]}}onMounted(load);function watch(e:any){if(!e.unlocked){ElMessage.info('该集需要购买本剧后解锁');return}$routerPush(e)}function $routerPush(e:any){if(e.video_url)location.hash='#/watch/'+route.params.id+'/'+e.id;else ElMessage.warning('暂无视频地址')}</script>
<template><section v-if="detail"><el-button text @click="$router.back()">← 返回</el-button><div class="detail"><div class="detail-cover"><img v-if="detail.cover" :src="detail.cover"><span v-else>SHORT DRAMA</span></div><div class="detail-main"><p class="eyebrow">{{detail.country}} · {{detail.language}}</p><h1>{{detail.title}}</h1><p>{{detail.description}}</p><div v-if="detail.is_paid" class="price">USD {{(Number(detail.price_cents||499)/100).toFixed(2)}}</div><el-tag :type="detail.is_paid?'warning':'success'">{{detail.is_paid?'付费剧':'免费'}}</el-tag><div class="actions"><el-button v-if="detail.is_paid" type="primary" size="large" @click="$router.push('/checkout/'+detail.id)">立即购买</el-button></div></div></div><el-card class="episodes"><template #header><b>剧集列表</b></template><div class="episode-list"><el-button v-for="e in episodes" :key="e.id" @click="watch(e)">第 {{e.episode_no}} 集 {{e.title}} <span v-if="!e.unlocked">🔒</span></el-button><el-empty v-if="!episodes.length" description="暂无剧集"/></div></el-card></section></template>